const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Point([121.4737, 31.2304]);
  const wuhan = ee.Geometry.Point([114.3055, 30.5928]);
  const startDate = '2020-04-20';
  const endDate = '2020-05-12';

  // Buffer for regional average (10km radius)
  const shanghaiRegion = shanghai.buffer(10000);
  const wuhanRegion = wuhan.buffer(10000);

  // 2. Data Acquisition
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density')
    .filterDate(startDate, endDate);

  const shanghaiCol = no2Collection.filterBounds(shanghaiRegion);
  const wuhanCol = no2Collection.filterBounds(wuhanRegion);

  const shanghaiSize = shanghaiCol.size().getInfo();
  const wuhanSize = wuhanCol.size().getInfo();

  console.log(`Shanghai images: ${shanghaiSize}`);
  console.log(`Wuhan images: ${wuhanSize}`);

  if (shanghaiSize === 0 || wuhanSize === 0) {
    console.log("No data for one or both cities.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Quality masking and processing
  function maskPoorQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  }

  const shanghaiFiltered = shanghaiCol.map(maskPoorQuality);
  const wuhanFiltered = wuhanCol.map(maskPoorQuality);

  // Create mean composites
  const shanghaiMean = shanghaiFiltered.mean();
  const wuhanMean = wuhanFiltered.mean();

  // 4. Calculate statistics with pixel counts
  const shanghaiStats = shanghaiMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: shanghaiRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const wuhanStats = wuhanMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: wuhanRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const shanghaiValue = shanghaiStats['tropospheric_NO2_column_number_density_mean'];
  const shanghaiCount = shanghaiStats['tropospheric_NO2_column_number_density_count'];
  const wuhanValue = wuhanStats['tropospheric_NO2_column_number_density_mean'];
  const wuhanCount = wuhanStats['tropospheric_NO2_column_number_density_count'];

  console.log(`Shanghai: Mean=${shanghaiValue}, Pixels=${shanghaiCount}`);
  console.log(`Wuhan: Mean=${wuhanValue}, Pixels=${wuhanCount}`);

  // 5. Validation & Final Answer
  if (shanghaiCount === 0 || wuhanCount === 0) {
    console.log("No valid pixels after quality masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (shanghaiValue === null || shanghaiValue === undefined || 
      wuhanValue === null || wuhanValue === undefined ||
      isNaN(shanghaiValue) || isNaN(wuhanValue)) {
    console.log("Calculation failed - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Convert from mol/m^2 to more readable units (x 1e6 for micromol/m^2)
  const shanghaiMicromol = shanghaiValue * 1e6;
  const wuhanMicromol = wuhanValue * 1e6;

  console.log(`Shanghai NO2: ${shanghaiMicromol.toFixed(2)} micromol/m^2`);
  console.log(`Wuhan NO2: ${wuhanMicromol.toFixed(2)} micromol/m^2`);

  if (shanghaiValue > wuhanValue) {
    console.log("Shanghai had higher tropospheric NO2 levels than Wuhan.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Shanghai did not have higher tropospheric NO2 levels than Wuhan.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
